create table if not exists public.offers (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, direction text not null check(direction in ('buy','sell')), source_currency char(3) not null, target_currency char(3) not null, exchange_rate numeric(20,8) not null check(exchange_rate>0), original_amount numeric(20,2) not null check(original_amount>0), remaining_amount numeric(20,2) not null check(remaining_amount>=0 and remaining_amount<=original_amount), description text, location text, status text not null default 'active' check(status in ('active','paused','filled','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.offers add column if not exists direction text; alter table public.offers add column if not exists source_currency char(3); alter table public.offers add column if not exists target_currency char(3); alter table public.offers add column if not exists exchange_rate numeric(20,8); alter table public.offers add column if not exists original_amount numeric(20,2); alter table public.offers add column if not exists remaining_amount numeric(20,2); alter table public.offers add column if not exists description text; alter table public.offers add column if not exists location text; alter table public.offers add column if not exists status text default 'active'; alter table public.offers add column if not exists created_at timestamptz default now(); alter table public.offers add column if not exists updated_at timestamptz default now();
